CREATE TABLE takeys (item INTEGER UNIQUE, value TEXT, FOREIGN KEY (item) REFERENCES items (id));
CREATE TABLE templates (item INTEGER, version INTEGER, template TEXT, FOREIGN KEY (item) REFERENCES items (id));
CREATE TABLE token_mechanism (item INTEGER, mechanism INTEGER, FOREIGN KEY (item) REFERENCES items (id));
CREATE TABLE tokens (item INTEGER, card_manufacturer VARCHAR(64), card_serial VARCHAR(64), card_model VARCHAR(64), card_label VARCHAR(64), slot_label VARCHAR(64), object_id VARCHAR(64), FOREIGN KEY (item) REFERENCES items (id));
CREATE TABLE x509super (item INTEGER, subj_hash INTEGER, pkey INTEGER, key_hash INTEGER, FOREIGN KEY (item) REFERENCES items (id), FOREIGN KEY (pkey) REFERENCES items (id));
INSERT INTO "x509super" VALUES(2,1480068581,1,1370403661);
CREATE INDEX i_settings_key_ ON settings (key_);
CREATE INDEX i_items_id ON items (id);
CREATE INDEX i_public_keys_item ON public_keys (item);
CREATE INDEX i_public_keys_hash ON public_keys (hash);
CREATE INDEX i_private_keys_item ON private_keys (item);
CREATE INDEX i_tokens_item ON tokens (item);
CREATE INDEX i_token_mechanism_item ON token_mechanism (item);
CREATE INDEX i_x509super_item ON x509super (item);
CREATE INDEX i_x509super_subj_hash ON x509super (subj_hash);
CREATE INDEX i_x509super_key_hash ON x509super (key_hash);
CREATE INDEX i_x509super_pkey ON x509super (pkey);
CREATE INDEX i_requests_item ON requests (item);
CREATE INDEX i_requests_hash ON requests (hash);
CREATE INDEX i_certs_item ON certs (item);
CREATE INDEX i_certs_hash ON certs (hash);
CREATE INDEX i_certs_iss_hash ON certs (iss_hash);
CREATE INDEX i_certs_serial ON certs (serial);
CREATE INDEX i_certs_issuer ON certs (issuer);
CREATE INDEX i_certs_ca ON certs (ca);
CREATE INDEX i_authority_item ON authority (item);
CREATE INDEX i_crls_item ON crls (item);
CREATE INDEX i_crls_hash ON crls (hash);
CREATE INDEX i_crls_iss_hash ON crls (iss_hash);
CREATE INDEX i_crls_issuer ON crls (issuer);
CREATE INDEX i_revocations_caId_serial ON revocations (caId, serial);
CREATE INDEX i_templates_item ON templates (item);
CREATE INDEX i_items_stamp ON items (stamp);
CREATE VIEW view_public_keys AS SELECT items.id, items.name, items.type AS item_type, items.date, items.source, items.comment, public_keys.type as key_type, public_keys.len, public_keys."public", private_keys.ownPass, tokens.card_manufacturer, tokens.card_serial, tokens.card_model, tokens.card_label, tokens.slot_label, tokens.object_id FROM public_keys LEFT JOIN items ON public_keys.item = items.id LEFT JOIN private_keys ON private_keys.item = public_keys.item LEFT JOIN tokens ON public_keys.item = tokens.item;
CREATE VIEW view_certs AS SELECT items.id, items.name, items.type, items.date AS item_date, items.source, items.comment, x509super.pkey, certs.serial AS certs_serial, certs.issuer, certs.ca, certs.cert, authority.template, authority.crlExpire, authority.crlNo AS auth_crlno, authority.crlDays, authority.dnPolicy, revocations.serial, revocations.date, revocations.invaldate, revocations.crlNo, revocations.reasonBit FROM certs LEFT JOIN items ON certs.item = items.id LEFT JOIN x509super ON x509super.item = certs.item LEFT JOIN authority ON authority.item = certs.item LEFT JOIN revocations ON revocations.caId = certs.issuer AND revocations.serial = certs.serial;
CREATE VIEW view_requests AS SELECT items.id, items.name, items.type, items.date, items.source, items.comment, x509super.pkey, requests.request, requests.signed FROM requests LEFT JOIN items ON requests.item = items.id LEFT JOIN x509super ON x509super.item = requests.item;
CREATE VIEW view_crls AS SELECT items.id, items.name, items.type, items.date, items.source, items.comment, crls.num, crls.issuer, crls.crl FROM crls LEFT JOIN items ON crls.item = items.id;
CREATE VIEW view_templates AS SELECT items.id, items.name, items.type, items.date, items.source, items.comment, templates.version, templates.template FROM templates LEFT JOIN items ON templates.item = items.id;
CREATE VIEW view_private AS SELECT name, private FROM private_keys JOIN items ON items.id = private_keys.item;
COMMIT;
